B.Locales.ptBR["Item name"]="Nome do item"
B.Locales.ptBR["Count / want"]="Quantidade / desejado"
B.Locales.ptBR["Font, colour, frame style and glow follow the Buff reminder."]="Fonte, cor, estilo de moldura e brilho seguem o lembrete de bônus."
B.Locales.ptBR["(selected)"]="(escolhido)"
B.Locales.ptBR["Left-click: Supplies options. Right-click: snooze for 10 minutes. Drag to move."]="Clique esquerdo: opções de suprimentos. Clique direito: adiar por 10 minutos. Arraste para mover."
